/// 결제(PG) 설정 — **상점 플랫폼 OWNER 전용**. ADMIN·STAFF·PAT·M2M·3rd-party 앱 토큰은 스코프가 있어도
/// 403 `INSUFFICIENT_ROLE`입니다(조회 포함). OWNER 여부는 요청 시점의 상점 멤버십으로 다시 확인하므로
/// 양도·강등 직후에도 바로 403입니다. 비밀 값(시크릿 키·API Secret·웹훅 시크릿)은 요청으로만 보내고
/// 응답에는 `secrets[].masked`(앞 4자리 마스킹)만 나옵니다.
class StoreClientPaymentSettings {
  StoreClientPaymentSettings._(this._http);

  final _Https _http;

  /// `GET /v1/store/payment-settings` — 라우팅 모드와 지원 PG 전부(연결된 것은 우선순위순).
  Future<PaymentSettings> get() async => _http.store.request('GET', '/store/payment-settings', paymentSettingsSchema);

  /// `PUT /v1/store/payment-settings` — `priority`에는 연결된 PG를 개수와 무관하게 모두 한 번씩 나열합니다
  /// (빠지거나 중복되면 400 `INVALID_PRIORITY`). 진행 중인 결제에는 적용되지 않습니다.
  Future<PaymentSettings> update(UpdatePaymentSettingsRequest body) async => _http.store.request(
      'PUT',
      '/store/payment-settings',
      paymentSettingsSchema,
      RequestOptions(body: updatePaymentSettingsRequestSchema.parse(body).toJson()));

  /// `PUT /v1/store/payment-providers/tosspayments` — 자격 증명 세트 저장. `environment`는 **저장할 세트**(`TEST`·`LIVE`)이고
  /// 결제에 쓰는 세트는 샌드박스 스위치(`setSandboxMode`)가 정합니다. 처음 연결하면 `enabled: false`·`sandboxMode: true`로 만들어집니다.
  /// 같은 가맹점(`clientKey`)이면 그 세트를 갱신하고, 가맹점이 바뀌면 새 세트를 만들고 이전 세트는 보관합니다
  /// (`retiredCredentialCount` +1, 이미 받은 결제의 환불·대사에 계속 쓰입니다). `secretKey`·`webhookSecret`을 생략하면
  /// 현재 세트의 값을 이어받고 `webhookSecret: null`은 삭제입니다. 저장하면 그 세트의 `lastVerification`이 초기화됩니다.
  ///
  /// 에러: 400 `PAYMENT_PROVIDER_INCOMPLETE`(시크릿 키 없음) · 400 `INVALID_CREDENTIALS`(형식·환경 불일치) ·
  /// 409 `PAYMENT_PROVIDER_VERIFICATION_FAILED`(라이브 사용 중인 PG의 LIVE 세트 가맹점을 바꾸려는데 저장 전 연결 테스트 실패.
  /// 저장되지 않습니다. 같은 가맹점의 비밀 값 교체는 검사하지 않습니다).
  Future<PaymentProvider> upsertTossPayments(UpsertTossPaymentsProviderRequest body) async => _http.store.request(
      'PUT',
      '/store/payment-providers/tosspayments',
      paymentProviderSchema,
      RequestOptions(body: upsertTossPaymentsProviderRequestSchema.parse(body).toJson()));

  /// `PUT /v1/store/payment-providers/portone` — 자격 증명 세트 저장. 규칙·에러는 `upsertTossPayments`와 같습니다
  /// (가맹점 식별자는 `storeId`, 비밀 필드는 `apiSecret`·`webhookSecret`). 400 `INVALID_CREDENTIALS`에는 채널 키 중복이 포함됩니다.
  Future<PaymentProvider> upsertPortOne(UpsertPortOneProviderRequest body) async => _http.store.request(
      'PUT',
      '/store/payment-providers/portone',
      paymentProviderSchema,
      RequestOptions(body: upsertPortOneProviderRequestSchema.parse(body).toJson()));

  /// `PUT /v1/store/payment-providers/kakaopay` — 카카오페이(직접 연동) 자격 증명 세트 저장. 규칙·에러는 `upsertTossPayments`와 같습니다
  /// (가맹점 식별자는 `cid`, 비밀 필드는 `secretKey`). 결제 옵션은 간편결제(`KAKAOPAY`) 하나입니다.
  Future<PaymentProvider> upsertKakaoPay(UpsertKakaoPayProviderRequest body) async => _http.store.request(
      'PUT',
      '/store/payment-providers/kakaopay',
      paymentProviderSchema,
      RequestOptions(body: upsertKakaoPayProviderRequestSchema.parse(body).toJson()));

  /// `PUT /v1/store/payment-providers/naverpay` — 네이버페이 결제형(직접 연동) 자격 증명 세트 저장. 규칙·에러는 `upsertTossPayments`와 같습니다
  /// (가맹점 식별자는 `clientId`, 비밀 필드는 `clientSecret`). 결제 옵션은 간편결제(`NAVERPAY`) 하나입니다.
  Future<PaymentProvider> upsertNaverPay(UpsertNaverPayProviderRequest body) async => _http.store.request(
      'PUT',
      '/store/payment-providers/naverpay',
      paymentProviderSchema,
      RequestOptions(body: upsertNaverPayProviderRequestSchema.parse(body).toJson()));

  /// `PUT /v1/store/payment-providers/paypal` — PayPal(직접 연동) 자격 증명 세트 저장. 규칙·에러는 `upsertTossPayments`와 같습니다
  /// (가맹점 식별자는 `clientId`, 비밀 필드는 `clientSecret`). 결제 옵션은 PayPal 간편결제 하나이고 `currencies`의 외화 주문서에만 나옵니다.
  Future<PaymentProvider> upsertPayPal(UpsertPayPalProviderRequest body) async => _http.store.request(
      'PUT',
      '/store/payment-providers/paypal',
      paymentProviderSchema,
      RequestOptions(body: upsertPayPalProviderRequestSchema.parse(body).toJson()));

  /// `PATCH /v1/store/payment-providers/{provider}` — 사용 여부(`enabled`)·샌드박스 스위치(`sandboxMode`) 변경.
  /// 하나 이상 보내야 합니다(아니면 요청 전에 ZodError). 검증을 모두 통과해야 한 번에 적용됩니다(부분 적용 없음).
  /// 끈 PG로 승인된 결제의 환불은 계속 그 PG로 갑니다.
  ///
  /// 에러
  /// - 404 `PAYMENT_PROVIDER_NOT_FOUND`: 연결되지 않은 PG
  /// - 409 `PAYMENT_PROVIDER_INCOMPLETE`: 켜려는데 활성 환경(샌드박스면 TEST, 아니면 LIVE) 세트가 없거나 불완전
  /// - 409 `LIVE_GATE_NOT_MET`: `sandboxMode: false`(라이브 전환)인데 개방 조건 미충족. `ApiError.details`가
  ///   `{ conditions: LiveGateCondition[] }`(조건별 `met`)입니다. `liveGateErrorDetailsSchema`로 파싱합니다
  ///
  /// `sandboxMode: true`는 항상 허용되고 즉시 실결제가 멈춥니다.
  Future<PaymentProvider> updateProvider(String provider, UpdatePaymentProviderRequest body) async =>
      _http.store.request('PATCH', '/store/payment-providers/${encodeURIComponent(pgProviderSchema.parse(provider))}',
          paymentProviderSchema, RequestOptions(body: updatePaymentProviderRequestSchema.parse(body).toJson()));

  /// 샌드박스 스위치만 바꿉니다 — `updateProvider(provider, { sandboxMode })`와 같습니다.
  /// `false`(라이브 전환)는 409 `LIVE_GATE_NOT_MET`(`ApiError.details.conditions`)가 날 수 있습니다.
  Future<PaymentProvider> setSandboxMode(String provider, bool sandboxMode) =>
      updateProvider(provider, UpdatePaymentProviderRequest(sandboxMode: sandboxMode));

  /// `PUT /v1/store/payment-providers/{provider}/platform-test-keys` — 테스트모드 키 활성화. 켜면 sayren 지정 테스트 키를 TEST 세트로 저장하고 PG를 켭니다
  /// (OWNER·ADMIN, 에이전트도 쓸 수 있습니다). 에러: 409 `PLATFORM_TEST_KEYS_UNAVAILABLE`(그 PG의 지정 테스트 키가 없습니다).
  Future<PaymentStatusProvider> setPlatformTestKeys(PgProvider provider, bool enabled) async => _http.store.request(
      'PUT',
      '/store/payment-providers/${encodeURIComponent(pgProviderSchema.parse(provider))}/platform-test-keys',
      paymentStatusProviderSchema,
      RequestOptions(body: setPlatformTestKeysRequestSchema.parse({'enabled': enabled}).toJson()));

  /// `GET /v1/store/payment-status` — 지원 PG와 연결·사용·테스트모드 키 상태(비밀 값 없음, OWNER·ADMIN·에이전트).
  Future<PaymentStatus> status() async => _http.store.request('GET', '/store/payment-status', paymentStatusSchema);

  /// `DELETE /v1/store/payment-providers/{provider}` (204) — 연결 해제. 결제 이력과 무관하게 허용됩니다.
  /// 모든 세트는 보관되고 PG 설정에서 사라집니다. 이미 받은 결제의 취소·환불·대사는 보관된 자격 증명으로 계속 처리됩니다.
  /// 404 `PAYMENT_PROVIDER_NOT_FOUND`.
  Future<void> disconnect(PgProvider provider) async => _http.store
      .requestVoid('DELETE', '/store/payment-providers/${encodeURIComponent(pgProviderSchema.parse(provider))}');

  /// `DELETE /v1/store/payment-providers/{provider}/credentials/{TEST|LIVE}` (200) — 활성 환경이 아닌 세트 하나를 보관 처리하고
  /// 갱신된 `PaymentProvider`를 돌려줍니다. 보관된 세트는 그 세트로 받은 결제의 환불에 계속 쓰입니다.
  ///
  /// 에러: 404 `PAYMENT_PROVIDER_NOT_FOUND`(미연결 PG) · 404 `PAYMENT_CREDENTIAL_NOT_FOUND`(등록되지 않은 세트) ·
  /// 409 `PAYMENT_CREDENTIAL_ACTIVE`(지금 결제에 쓰는 세트. 먼저 `setSandboxMode`로 스위치를 바꿉니다).
  ///
  /// `DELETE /v1/store/payment-providers/{provider}/credentials/{environment}`
  Future<PaymentProvider> removeCredentialSet(PgProvider provider, PgEnvironment environment) async => _http.store.request(
      'DELETE',
      '/store/payment-providers/${encodeURIComponent(pgProviderSchema.parse(provider))}/credentials/${encodeURIComponent(pgEnvironmentSchema.parse(environment))}',
      paymentProviderSchema);

  /// `POST /v1/store/payment-providers/{provider}/verify` — 저장된 세트로 연결 테스트하고 결과를 그 세트에 저장합니다.
  /// `environment`를 생략하면 활성 환경 세트를 테스트합니다. 실패해도 200이고 `result: "FAILED"`와 `message`에 사유가 옵니다.
  /// 라이브 개방 조건 `TEST_CONNECTION`·`LIVE_CONNECTION`은 이 결과로 판정합니다. 404 `PAYMENT_PROVIDER_NOT_FOUND`.
  Future<PaymentProviderVerification> verify(String provider, [VerifyPaymentProviderRequest? body]) async =>
      _http.store.request(
          'POST',
          '/store/payment-providers/${encodeURIComponent(pgProviderSchema.parse(provider))}/verify',
          paymentProviderVerificationSchema,
          RequestOptions(body: verifyPaymentProviderRequestSchema.parse(body ?? const <String, Object?>{}).toJson()));
}

