/// `client.store` 네임스페이스입니다.
class StoreClientStore {
  StoreClientStore._(this._http);

  final _Https _http;

  /// `GET /v1/store`
  Future<Store> get() async => _http.store.request('GET', '/store', storeSchema);

  /// `PATCH /v1/store` — 스코프 `store:rw`. 바꿀 필드만 보냅니다. `analyticsAllowedOrigins`는 방문 분석 수집을 받을
  /// 스토어프론트 오리진 목록입니다(빈 배열이면 모든 오리진 허용).
  Future<Store> update(UpdateStoreRequest body) async => _http.store
      .request('PATCH', '/store', storeSchema, RequestOptions(body: updateStoreRequestSchema.parse(body).toJson()));

  /// `GET /v1/store/point-policy` — 스코프 `promotion:r`. 적립금 정책(리뷰 적립·유효 기간)과 준비 여부(`available`), 상점에 보일 안내(`notice`).
  /// 정책을 정하지 않았으면 모두 끔입니다(#93).
  Future<StorePointPolicy> getPointPolicy() async =>
      _http.store.request('GET', '/store/point-policy', storePointPolicySchema);

  /// `PUT /v1/store/point-policy` — 스코프 `promotion:rw`. 준 항목만 바꿉니다. 에이전트 요청은 승인 대상입니다.
  /// 에러: 400 `POINT_EXPIRY_REQUIRED`(리뷰 적립을 켜는데 유효 기간이 없음).
  Future<StorePointPolicy> updatePointPolicy(UpdatePointPolicyRequest body) async => _http.store.request(
      'PUT',
      '/store/point-policy',
      storePointPolicySchema,
      RequestOptions(body: updatePointPolicyRequestSchema.parse(body).toJson()));

  /// `GET /v1/store/members`
  Future<List<StoreMember>> listMembers() async =>
      _http.store.request('GET', '/store/members', z.array<StoreMember>(storeMemberSchema));

  /// `PATCH /v1/store/members/{userId}` — 스코프 `member:rw`. OWNER는 바꿀 수 없고 ADMIN 지정·ADMIN 변경은 OWNER만 합니다.
  Future<StoreMemberRoleUpdated> updateMemberRole(String userId, UpdateMemberRoleRequest body) async =>
      _http.store.request('PATCH', '/store/members/${encodeURIComponent('$userId')}', storeMemberRoleUpdatedSchema,
          RequestOptions(body: updateMemberRoleRequestSchema.parse(body).toJson()));

  /// `DELETE /v1/store/members/{userId}` (204) — OWNER는 내보낼 수 없고 ADMIN은 OWNER만 내보냅니다.
  Future<void> removeMember(String userId) async =>
      _http.store.requestVoid('DELETE', '/store/members/${encodeURIComponent('$userId')}');

  /// `GET /v1/store/invitations` — 구성원 초대 목록입니다. [status]로 거릅니다.
  Future<List<Invitation>> listInvitations({String? status}) async => _http.store.request(
      'GET', '/store/invitations', z.array<Invitation>(invitationSchema), RequestOptions(query: {'status': status}));

  /// `POST /v1/store/invitations` (201) — 스코프 `member:rw`. 초대 메일을 보냅니다. 발송 결과는 응답의
  /// `deliveryStatus`입니다(발송이 실패해도 초대는 만들어집니다). 상점·초대한 사람·받는 주소별 발송 한도가 있습니다(429, `details.limit`).
  Future<Invitation> invite(InviteMemberRequest body) async => _http.store.request('POST', '/store/invitations',
      invitationSchema, RequestOptions(body: inviteMemberRequestSchema.parse(body).toJson()));

  /// `POST /v1/store/invitations/{invitationId}/resend` — 새 수락 링크로 다시 보냅니다. 이전 링크는 무효가 되고 만료가 다시 7일이 됩니다.
  Future<Invitation> resendInvitation(String invitationId) async =>
      _http.store.request('POST', '/store/invitations/${encodeURIComponent('$invitationId')}/resend', invitationSchema);

  /// `DELETE /v1/store/invitations/{invitationId}` (204) — 대기 중 초대를 취소합니다.
  Future<void> cancelInvitation(String invitationId) async =>
      _http.store.requestVoid('DELETE', '/store/invitations/${encodeURIComponent('$invitationId')}');
}
